// Verify the HMAC signature from LendLoop (Convex) on the raw request body.
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
const item = $input.first();
const header = item.json.headers['x-lendloop-signature'] || '';
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

const parts = Object.fromEntries(header.split(',').map((p) => p.trim().split('=')));
const t = Number(parts.t);
const now = Math.floor(Date.now() / 1000);
let valid = Boolean(secret && secret.length >= 32 && Number.isInteger(t) && parts.v1 && Math.abs(now - t) <= 300);
if (valid) {
  const expected = crypto.createHmac('sha256', secret).update(`${t}.${raw}`).digest('hex');
  valid = expected.length === parts.v1.length &&
    crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(parts.v1));
}
// Never pass the body on when the signature is bad.
return [{ json: valid ? { valid: true, event: JSON.parse(raw) } : { valid: false } }];

// Mock email: build the notice and log it. Swap this node for a real email node in production.
const { event } = $input.first().json;
const { loan, recipient, otherParty } = event;
const days = `${loan.startDate} to ${loan.endDate}`;
const subjects = {
  'loan.requested': `${otherParty.firstName} wants to borrow your ${loan.tool.name}`,
  approved: `${otherParty.firstName} said yes: ${loan.tool.name}`,
  declined: `${otherParty.firstName} can't lend the ${loan.tool.name} this time`,
  returned: `Thanks for returning the ${loan.tool.name}`,
};
const subject = event.event === 'loan.requested' ? subjects['loan.requested'] : subjects[loan.status] ?? `Update on ${loan.tool.name}`;
const text = `Hi ${recipient.firstName},\n\n${subject} (${loan.tool.ref}, ${days}).\nOpen LendLoop to see the details.`;
console.log(`[mock email] to=${recipient.email ?? 'no-email'} subject="${subject}"`);
return [{ json: { event, mail: { to: recipient.email, subject, text, sentAt: new Date().toISOString() } } }];

// Sign the write-back to LendLoop. The idempotency key is the Convex event id,
// so a retried webhook never records the same notice twice.
const crypto = require('crypto');
const { event, mail } = $input.first().json;
const payload = {
  idempotencyKey: `notify:${event.eventId}`,
  loanId: event.loan.id,
  kind: event.recipient.role === 'owner' ? 'owner_notified' : 'borrower_notified',
  detail: mail.subject,
};
const body = JSON.stringify(payload);
const t = Math.floor(Date.now() / 1000);
const v1 = crypto.createHmac('sha256', $env.CONVEX_WEBHOOK_SECRET).update(`${t}.${body}`).digest('hex');
return [{ json: { body, signature: `t=${t},v1=${v1}` } }];
